},{"t":"[A] 3 × 5 min Tempo (threshold), 90 sec jog between","lv":"HS"},{"t":"[B] 3 × 4 min Tempo (threshold), 90 sec jog between","lv":"HS"},{"t":"[C] 2 × 4 min Tempo (threshold), 90 sec jog between","lv":"HS"},{"t":"Cool-down: 10–15 min Easy.","lv":"HS"},{"t":"Optional: short Strength M · Maintenance if there's time and runners feel good.","lv":"HS"}]},"gfocus":{"Mid Distance":"Threshold"},"sess":{"HS":{"kind":"official","title":"Threshold","obj":"Official season begins","cls":"Official practice (IHSAA start date: confirm)","wk":"Week 12 · official season"}}},{"day":"Wed","focus":{"HS":"Recovery run"},"all":[],"groups":{"Distance":[{"t":"[A] 25–35 min recovery run, slow end of Easy","lv":"HS"},{"t":"[B] 20–30 min recovery run, slow end of Easy","lv":"HS"},{"t":"[C] 15–20 min recovery run, slow end of Easy","lv":"HS"}],"Mid Distance":[{"t":"[A] 20–30 min recovery run, slow end of Easy","lv":"HS"},{"t":"[B] 15–25 min recovery run, slow end of Easy","lv":"HS"},{"t":"[C] 10–20 min recovery run, slow end of Easy","lv":"HS"}]},"gfocus":{"Mid Distance":"Recovery run"},"sess":{"HS":{"kind":"official","title":"Recovery run","obj":"Official season begins","cls":"Official practice (IHSAA start date: confirm)","wk":"Week 12 · official season"}}},{"day":"Thu","focus":{"HS":"Short hills"},"all":[],"groups":{"Distance":[{"t":"Warm-up: 15 min Easy + drills.","lv":"HS"},{"t":"4 × 30m progressive accelerations, full recovery","lv":"HS"},{"t":"BC Short Hills: 6–8 × 10 sec hill sprints on a steep hill, near-max effort, walk down + 60–90 sec (full recovery)","lv":"HS"},{"t":"2 × 150m at Rep pace (fast and relaxed), 3–4 min recovery","lv":"HS"},{"t":"[Crossover] [Hybrid] Optional instead of the 150s: 3 × 300m at 800 pace, 4–5 min recovery (first 800-specific Thursday)","lv":"HS"},{"t":"Hills: run tall, quick arms, no grinding. Effort counts, not pace.","lv":"HS"},{"t":"Cool-down: 10 min Easy.","lv":"HS"}],"Mid Distance":[{"t":"Warm-up: 10–15 min Easy + drills.","lv":"HS"},{"t":"4 × 30m