  cur jsonb; w jsonb; d jsonb; wk jsonb; days jsonb; dd jsonb; keep jsonb; g text; grp jsonb; f jsonb;
  fw int; fd int; nd int := 0;
begin
  select value into cur from public.hub_data where key = 'workouts' for update;
  if cur is null or jsonb_typeof(cur) <> 'array' then cur := '[]'::jsonb; end if;

  for w in select * from jsonb_array_elements(plan) loop
    fw := null;
    for i in 0 .. jsonb_array_length(cur) - 1 loop
      if cur -> i ->> 'start' = w ->> 'start' then fw := i; end if;
    end loop;
    if fw is null then cur := cur || jsonb_build_array(w); nd := nd + jsonb_array_length(w -> 'days'); continue; end if;

    wk := cur -> fw;
    days := coalesce(wk -> 'days', '[]'::jsonb);
    for d in select * from jsonb_array_elements(w -> 'days') loop
      nd := nd + 1;
      fd := null;
      for j in 0 .. jsonb_array_length(days) - 1 loop
        if days -> j ->> 'day' = d ->> 'day' then fd := j; end if;
      end loop;
      if fd is null then days := days || jsonb_build_array(d); continue; end if;

      dd := days -> fd;
      if dd -> 'groups' is null or jsonb_typeof(dd -> 'groups') <> 'object' then dd := jsonb_set(dd, '{groups}', '{}'::jsonb); end if;
      for g, grp in select * from jsonb_each(d -> 'groups') loop
        select coalesce(jsonb_agg(x), '[]'::jsonb) into keep
          from jsonb_array_elements(coalesce(dd -> 'groups' -> g, '[]'::jsonb)) x
          where coalesce(x ->> 'lv', '') <> 'HS';
        dd := jsonb_set(dd, array['groups', g], keep || grp);
      end loop;
      dd := jsonb_set(dd, '{gfocus}', coalesce(dd -> 'gfocus', '{}'::jsonb) || (d -> 'gfocus'));
      dd := jsonb_set(dd, '{sess}', coalesce(dd -> 'sess', '{}'::jsonb) || (d -> 'sess'));
      -- HS focus label: keep any JH label
      f := dd -> 'focus';
      if f is null or jsonb_typeof(f) = 'null' or (jsonb_typeof(f) = 'string' and f #>> '{}' = '') then
        f := d -> 'focus';
      elsif jsonb_typeof(f) = 'string' then
        f := jsonb_build_object('JH', f #>> '{}', 'HS', d -> 'focus' ->> 'HS');
      else
        f := f || jsonb_build_object('HS', d -> 'focus' ->> 'HS');
      end if;
      dd := jsonb_set(dd, '{focus}', f);
      if dd -> 'all' is null then dd := dd || '{"all":[]}'::jsonb; end if;
      days := jsonb_set(days, array[fd::text], dd);
    end loop;

    select jsonb_agg(x order by array_position(array['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], x ->> 'day'))
      into days from jsonb_array_elements(days) x;
    cur := jsonb_set(cur, array[fw::text], jsonb_set(wk, '{days}', days));
  end loop;

  select jsonb_agg(x order by x ->> 'start') into cur from jsonb_array_elements(cur) x;
  insert into public.hub_data (key, value, updated_at) values ('workouts', cur, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  raise notice 'Winter plan posted: % days updated (Dec 1 to Feb 21). % weeks in total.', nd, jsonb_array_length(cur);
end
$do$;
